            $stopped += "worker:$($worker.ProcessId)"
            Write-DKillFastLine ("DKILL_STOP_OK generated worker pid={0}" -f $worker.ProcessId) DarkCyan
        } catch {
            $failures += "worker:$($worker.ProcessId): $($_.Exception.Message)"
            Write-DKillFastLine ("DKILL_STOP_FAIL generated worker pid={0}: {1}" -f $worker.ProcessId,$_.Exception.Message) Red
        }
    }

